export function applyEditorialEnrichments(dreams) {
  for (const dream of dreams) {
    const enrichment = editorialEnrichments[dream.slug];
    if (!enrichment) continue;
    const { coreField, coreAddition, secondaryCoreField, secondaryCoreAddition, ...fields } = enrichment;
    Object.assign(dream, fields);
    if (coreField && coreAddition) {
      dream[coreField] = `${dream[coreField]}\n\n${coreAddition}`;
    }
    if (secondaryCoreField && secondaryCoreAddition) {
      dream[secondaryCoreField] = `${dream[secondaryCoreField]}\n\n${secondaryCoreAddition}`;
    }
  }
}
